# TableDefinition: dataclass + validator
from dataclasses import dataclass, field
from typing import Any

@dataclass
class Tabledefinition:
    table: str = None  # Table name
    columns: list = None  # Column defs
    primary_key: str = None  # PK column
    engine: str = None  # Storage engine

REQUIRED = ["table", "columns", "primary_key", "engine"]

def validate(rec: dict) -> list:
    errors = []
    for f in REQUIRED:
        if f not in rec or rec[f] is None:
            errors.append(f'missing: {f}')
    return errors

sample = {'table': 'orders', 'columns': [{'name': 'id', 'type': 'uuid'}, {'name': 'total', 'type': 'numeric'}], 'primary_key': 'id', 'engine': 'innodb'}
print('validation errors:', validate(sample))
print('record ok:', not validate(sample))

